mapper.select:
/* com.portal.user.poll.qmc.QustnrManageMapper.selectQustnrManageList */ SELECT a.QESTNR_ID AS qestnrId, a.QUSTNR_SJ AS qestnrSj, a.QUSTNR_PURPS AS qestnrPurps, a.QUSTNR_WRITNG_GUIDANCE_CN AS qestnrWritngGuidanceCn, DATE_FORMAT(a.QUSTNR_BGNDE, '%Y-%m-%d') AS qestnrBeginDe, DATE_FORMAT(a.QUSTNR_ENDDE, '%Y-%m-%d') AS qestnrEndDe, a.QUSTNR_TRGET AS qestnrTrget, a.QUSTNR_TMPLAT_ID AS qestnrTmplatId, DATE_FORMAT(a.FRST_REGIST_PNTTM, '%Y-%m-%d') AS FRST_REGIST_PNTTM, a.FRST_REGISTER_ID, ( SELECT u.USER_NM FROM COMVNUSERMASTER u WHERE u.ESNTL_ID = a.FRST_REGISTER_ID ) AS FRST_REGISTER_NM, DATE_FORMAT(a.LAST_UPDT_PNTTM, '%Y-%m-%d') AS LAST_UPDT_PNTTM, a.LAST_UPDUSR_ID FROM LETTNQESTNRINFO a WHERE 1 = 1
AND a.QUSTNR_SJ LIKE CONCAT('%', #{searchKeyword}, '%')
AND a.FRST_REGISTER_ID IN ( SELECT u.ESNTL_ID FROM COMVNUSERMASTER u WHERE u.USER_NM LIKE CONCAT('%', #{searchKeyword}, '%') )
ORDER BY a.FRST_REGIST_PNTTM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.user.poll.qmc.QustnrManageMapper.selectQustnrManageListCnt */ SELECT COUNT(*) AS totcnt FROM LETTNQESTNRINFO a WHERE 1 = 1
AND a.QUSTNR_SJ LIKE CONCAT('%', #{searchKeyword}, '%')
AND a.FRST_REGISTER_ID IN ( SELECT u.ESNTL_ID FROM COMVNUSERMASTER u WHERE u.USER_NM LIKE CONCAT('%', #{searchKeyword}, '%') )
